const lines = msg.payload.split('\n');
const headers = lines[0].split(',');
const retailers = [];
for (let i = 1; i < lines.length; i++) {
    const row = lines[i].split(',');
    if (row.length < headers.length) continue;
    const r = {};
    for (let j = 0; j < headers.length; j++) {
        r[headers[j].trim()] = row[j].trim();
    }
    ['dsc','sub','off_pk','sh_pk','pk_pk','off_fit','sh_fit','pk_fit','sp_fit',
     'off_s','off_e','pk_s','pk_e','sp_s','sp_e','sp_limit','exp_s','exp_e','exp_rate','base','nw'
    ].forEach(f => { r[f] = parseFloat(r[f]) || 0; });
    r.sensor_id = 'sensor.retailer_' + r.name.toLowerCase().replace(/\s+/g, '_') + '_daily';
    retailers.push(r);
}
flow.set('retailers', retailers);
node.warn('Energy Retailer Comparitor starting - tracked retailers: ' + retailers.map(r => r.name).join(', '));
return null;

const retailers = flow.get('retailers');
if (!retailers || retailers.length === 0) { return null; }
const csvData = msg.payload;
const lines = csvData.split('\n');
// node.warn('Total lines: ' + lines.length);
for (let i = 1; i < Math.min(lines.length, 4); i++) {
    const row = lines[i].split(',');
    if (row.length < 14) continue;
    // node.warn('First rows: created=[' + row[0].trim() + '] PE=[' + row[12].trim() + ']');
}
for (let i = Math.max(1, lines.length - 4); i < lines.length; i++) {
    const row = lines[i].split(',');
    if (row.length < 14) continue;
    // node.warn('Last rows: created=[' + row[0].trim() + '] PE=[' + row[12].trim() + ']');
}
const NW_OFFPEAK = 0.051535;
const NW_PEAK = 0.29245;
const NW_PEAK_START = 15;
const NW_PEAK_END = 21;
const FLOW_EXPORT_KW = 18;
function getNetworkCost(dt) {
    const hour = dt.getHours();
    const dow = dt.getDay();
    if (dow >= 1 && dow <= 5 && hour >= NW_PEAK_START && hour < NW_PEAK_END) return NW_PEAK;
    return NW_OFFPEAK;
}
function pad2(n) { return n < 10 ? '0' + n : '' + n; }
function toLocalDateStr(d) { return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate()); }
const now = new Date();
const today = toLocalDateStr(now);
const yesterday = new Date(now);
yesterday.setDate(yesterday.getDate() - 1);
const yesterdayStr = toLocalDateStr(yesterday);
let billingYear = now.getFullYear();
let billingMonth = now.getMonth();
if (now.getDate() < 4) { billingMonth--; if (billingMonth < 0) { billingMonth = 11; billingYear--; } }
const billingStart = new Date(billingYear, billingMonth, 4);
const billingEnd = new Date(billingYear, billingMonth + 1, 3, 23, 59, 59);
const billingStartStr = toLocalDateStr(billingStart);
const billingEndStr = toLocalDateStr(billingEnd);
let twapSum = 0, twapCount = 0, lwapNum = 0, lwapDen = 0;
let bpPrevOff = 0, bpPrevSh = 0, bpPrevPk = 0, bpPrevDay = '';
for (let i = 1; i < lines.length; i++) {
    const row = lines[i].split(',');
    if (row.length < 14) continue;
    const periodEnding = row[12].trim();
    if (!periodEnding) continue;
    const rowDateStr = periodEnding.split(' ')[0];
    if (rowDateStr >= billingStartStr && rowDateStr <= billingEndStr) {
        const dt = new Date(periodEnding.replace(' ', 'T'));
        const aemo = parseFloat(row[11]) || 0;
        const cumOff = parseFloat(row[1]) || 0;
        const cumSh = parseFloat(row[2]) || 0;
        const cumPk = parseFloat(row[3]) || 0;
        if (rowDateStr !== bpPrevDay) { bpPrevOff = 0; bpPrevSh = 0; bpPrevPk = 0; bpPrevDay = rowDateStr; }
        const importKwh = Math.max(0, (cumOff - bpPrevOff) + (cumSh - bpPrevSh) + (cumPk - bpPrevPk));
        bpPrevOff = cumOff; bpPrevSh = cumSh; bpPrevPk = cumPk;
        const inclNW = aemo + getNetworkCost(dt);
        twapSum += inclNW; twapCount++;
        lwapNum += inclNW * importKwh; lwapDen += importKwh;
    }
}
const twap = twapCount > 0 ? twapSum / twapCount : 0;
const lwap = lwapDen > 0 ? lwapNum / lwapDen : 0;
const pea = (lwap - twap) - 0.017;
const flowPower = retailers.find(r => r.name === 'FlowPower');
const flowBase = flowPower ? flowPower.base : 0.33998;
const flowRate = flowBase + pea;
// node.warn('PEA: ' + pea.toFixed(6) + ', TWAP: ' + twap.toFixed(4) + ', LWAP: ' + lwap.toFixed(4) + ', Rate: ' + flowRate.toFixed(4) + ', Today: ' + today + ', BP: ' + billingStartStr + ' to ' + billingEndStr);

// --- DAILY SUMMARY ---
const dailyData = {};
let prevExport = 0, prevOffpeak = 0, prevShoulder = 0, prevPeak = 0, prevDay = '';
for (let i = 1; i < lines.length; i++) {
    const row = lines[i].split(',');
    if (row.length < 14) continue;
    const periodEnding = row[12].trim();
    if (!periodEnding) continue;
    const rowDateStr = periodEnding.split(' ')[0];
    if (rowDateStr < billingStartStr || rowDateStr > billingEndStr) {
        const rowDay = periodEnding.split(' ')[0];
        if (rowDay !== prevDay) { prevExport = 0; prevOffpeak = 0; prevShoulder = 0; prevPeak = 0; prevDay = rowDay; }
        continue;
    }
    if (rowDateStr !== prevDay) {
        prevExport = 0; prevOffpeak = 0; prevShoulder = 0; prevPeak = 0;
        if (!dailyData[rowDateStr]) {
            dailyData[rowDateStr] = {};
            retailers.forEach(r => {
                dailyData[rowDateStr][r.name] = {
                    import: 0, export: 0, net: 0,
                    adjImport: 0, adjExport: 0, expOutside45c: 0,
                    intervals: 0, lastTime: '', totalImport: 0, totalExport: 0,
                    eveningImport: 0,
                    spExportUsed: 0
                };
            });
        }
        prevDay = rowDateStr;
    }
    const cumOffpeak = parseFloat(row[1]) || 0;
    const cumShoulder = parseFloat(row[2]) || 0;
    const cumPeak = parseFloat(row[3]) || 0;
    const cumExport = parseFloat(row[4]) || 0;
    const aemoPrice = parseFloat(row[11]) || 0;
    const offpeakKwh = Math.max(0, cumOffpeak - prevOffpeak);
    const shoulderKwh = Math.max(0, cumShoulder - prevShoulder);
    const peakKwh = Math.max(0, cumPeak - prevPeak);
    const exportKwh = Math.max(0, cumExport - prevExport);
    prevOffpeak = cumOffpeak; prevShoulder = cumShoulder; prevPeak = cumPeak; prevExport = cumExport;
    const timeParts = periodEnding.split(' ')[1].split(':');
    const hour = parseInt(timeParts[0]);
    const minute = parseInt(timeParts[1]);
    const hourDecimal = hour + minute / 60;
    const totalImport = offpeakKwh + shoulderKwh + peakKwh;
    const dd = dailyData[rowDateStr];
    retailers.forEach(r => {
        const d = dd[r.name];
        d.intervals++;
        d.lastTime = periodEnding.split(' ')[1];
        d.totalImport += totalImport;
        d.totalExport += exportKwh;
        if (hourDecimal < 17.5 || hourDecimal >= 19.5) { d.expOutside45c -= exportKwh; }
        if (hourDecimal >= 18 && hourDecimal < 21) { d.eveningImport += totalImport; }
        if (r.model === 'fixed_tou') {
            d.import += offpeakKwh * r.off_pk + shoulderKwh * r.sh_pk + peakKwh * r.pk_pk;
            // Feed-in priority: super peak (with daily limit) > peak > off-peak > shoulder (default)
            if (hourDecimal >= r.sp_s && hourDecimal < r.sp_e && r.sp_limit > 0) {
                // Super peak window with daily export limit
                var remaining = r.sp_limit - d.spExportUsed;
                if (remaining > 0) {
                    var spPortion = Math.min(exportKwh, remaining);
                    var fbPortion = exportKwh - spPortion;
                    d.spExportUsed += spPortion;
                    d.export += spPortion * r.sp_fit;
                    if (fbPortion > 0) {
                        var fbRate = r.sh_fit;
                        if (hourDecimal >= r.pk_s && hourDecimal < r.pk_e) fbRate = r.pk_fit;
                        else if (hourDecimal >= r.off_s && hourDecimal < r.off_e) fbRate = r.off_fit;
                        d.export += fbPortion * fbRate;
                    }
                } else {
                    var fbRate = r.sh_fit;
                    if (hourDecimal >= r.pk_s && hourDecimal < r.pk_e) fbRate = r.pk_fit;
                    else if (hourDecimal >= r.off_s && hourDecimal < r.off_e) fbRate = r.off_fit;
                    d.export += exportKwh * fbRate;
                }
            } else {
                var expRate = r.sh_fit;
                if (hourDecimal >= r.sp_s && hourDecimal < r.sp_e) expRate = r.sp_fit;
                else if (hourDecimal >= r.pk_s && hourDecimal < r.pk_e) expRate = r.pk_fit;
                else if (hourDecimal >= r.off_s && hourDecimal < r.off_e) expRate = r.off_fit;
                d.export += exportKwh * expRate;
            }
        } else if (r.model === 'hybrid') {
            d.import += totalImport * flowRate;
        } else if (r.model === 'variable') {
            const dt = new Date(periodEnding.replace(' ', 'T'));
            const importRate = aemoPrice + getNetworkCost(dt);
            d.import += totalImport * importRate;
            d.export += exportKwh * aemoPrice * r.exp_rate;
        }
    });
}

// Build detailed daily summary
const dailySummary = {};
const days = Object.keys(dailyData).sort();
days.forEach(day => {
    const d0 = dailyData[day][retailers[0].name];
    dailySummary[day] = {
        totalImport: Math.round(d0.totalImport * 1000) / 1000,
        totalExport: Math.round(d0.totalExport * 1000) / 1000,
        retailers: {}
    };
    let cheapestNet = Infinity, cheapestName = '';
    retailers.forEach(r => {
        const d = dailyData[day][r.name];
        if (r.model === 'hybrid') {
            const lastTimeParts = d.lastTime.split(':');
            const lastHour = parseInt(lastTimeParts[0]);
            const lastMinute = parseInt(lastTimeParts[1]);
            const lastHourDecimal = lastHour + lastMinute / 60;
            const adjImport = Math.max(0, d.totalImport + d.expOutside45c);
            let adjExport;
            if (lastHourDecimal < 19.5) { adjExport = d.totalExport + d.expOutside45c; }
            else { adjExport = FLOW_EXPORT_KW; }
            d.adjImport = adjImport; d.adjExport = adjExport;
            d.export = adjExport * r.exp_rate;
            d.net = r.dsc + (adjImport * flowRate) - (adjExport * r.exp_rate);
        } else {
            d.net = d.import - d.export + r.dsc;
        }
        // Globird evening rebate
        if (r.name.indexOf('Globird') >= 0 && d.eveningImport < 0.09) {
            d.net -= 1.00;
            d.gloRebate = 1.00;
        } else {
            d.gloRebate = 0;
        }
        dailySummary[day].retailers[r.name] = {
            dsc: Math.round(r.dsc * 100) / 100,
            import: Math.round(d.import * 100) / 100,
            export: Math.round(d.export * 100) / 100,
            net: Math.round(d.net * 100) / 100,
            gloRebate: d.gloRebate || 0
        };
        if (d.net < cheapestNet) { cheapestNet = d.net; cheapestName = r.name; }
    });
    dailySummary[day].cheapest = cheapestName;
});

// --- TODAY'S COSTS ---
const todayData = dailyData[today];
const totals = {};
retailers.forEach(r => { totals[r.name] = { import: 0, export: 0, net: 0, adjImport: 0, adjExport: 0, expOutside45c: 0 }; });
if (todayData) {
    retailers.forEach(r => {
        const d = todayData[r.name];
        totals[r.name] = { import: Math.round(d.import * 100) / 100, export: Math.round(d.export * 100) / 100, net: Math.round(d.net * 100) / 100, adjImport: Math.round(d.adjImport * 100) / 100, adjExport: Math.round(d.adjExport * 100) / 100, expOutside45c: Math.round(d.expOutside45c * 100) / 100 };
    });
}
let cheapestName = retailers[0].name;
let cheapestNet = totals[retailers[0].name].net;
retailers.forEach(r => { if (totals[r.name].net < cheapestNet) { cheapestNet = totals[r.name].net; cheapestName = r.name; } });
const flowpowerNet = totals['FlowPower'] ? totals['FlowPower'].net : 0;

// --- 5-MIN DETAIL FOR ALL FIXED_TOU RETAILERS (ALL DATES IN BILLING PERIOD) ---
const fixedTouRetailers = retailers.filter(r => r.model === 'fixed_tou');
const fiveMinDetail = {};

if (fixedTouRetailers.length > 0) {
    // Build CSV lookup for ALL dates in billing period
    const csvByDate = {};
    let prevExport = 0, prevOff = 0, prevSh = 0, prevPk = 0, prevDay = '';
    for (let i = 1; i < lines.length; i++) {
        const row = lines[i].split(',');
        if (row.length < 14) continue;
        const periodEnding = row[12].trim();
        if (!periodEnding) continue;
        const rowDateStr = periodEnding.split(' ')[0];
        if (rowDateStr < billingStartStr || rowDateStr > billingEndStr) {
            const rowDay = periodEnding.split(' ')[0];
            if (rowDay !== prevDay) { prevExport = 0; prevOff = 0; prevSh = 0; prevPk = 0; prevDay = rowDay; }
            continue;
        }
        if (rowDateStr !== prevDay) {
            prevExport = 0; prevOff = 0; prevSh = 0; prevPk = 0; prevDay = rowDateStr;
            if (!csvByDate[rowDateStr]) csvByDate[rowDateStr] = {};
        }
        const cumOff = parseFloat(row[1]) || 0;
        const cumSh = parseFloat(row[2]) || 0;
        const cumPk = parseFloat(row[3]) || 0;
        const cumExp = parseFloat(row[4]) || 0;
        const oKwh = Math.max(0, cumOff - prevOff);
        const sKwh = Math.max(0, cumSh - prevSh);
        const pKwh = Math.max(0, cumPk - prevPk);
        const eKwh = Math.max(0, cumExp - prevExport);
        prevOff = cumOff; prevSh = cumSh; prevPk = cumPk; prevExport = cumExp;
        const timeParts = periodEnding.split(' ')[1].split(':');
        const csvHour = parseInt(timeParts[0]);
        const csvMin = parseInt(timeParts[1]);
        const roundedMin = Math.floor(csvMin / 5) * 5;
        const timeKey = pad2(csvHour) + ':' + pad2(roundedMin);
        csvByDate[rowDateStr][timeKey] = { oKwh, sKwh, pKwh, eKwh };
    }

    // Generate 5-min detail for each retailer and each date
    fixedTouRetailers.forEach(retailer => {
        fiveMinDetail[retailer.name] = {};
        const dates = Object.keys(csvByDate).sort();
        dates.forEach(dateStr => {
            const dayCSV = csvByDate[dateStr];
            const intervals = [];
            let eveningImport = 0;
            let spExportUsed = 0;
            for (let h = 0; h < 24; h++) {
                for (let m = 0; m < 60; m += 5) {
                    const timeKey = pad2(h) + ':' + pad2(m);
                    const hourDecimal = h + m / 60;
                    const csv = dayCSV[timeKey];
                    const oKwh = csv ? csv.oKwh : 0;
                    const sKwh = csv ? csv.sKwh : 0;
                    const pKwh = csv ? csv.pKwh : 0;
                    const eKwh = csv ? csv.eKwh : 0;
                    const totalImport = oKwh + sKwh + pKwh;
                    if (hourDecimal >= 18 && hourDecimal < 21) eveningImport += totalImport;
                    let touPeriod = 'Shoulder';
                    let impRate = retailer.sh_pk;
                    let expRate = retailer.sh_fit;
                    if (hourDecimal >= retailer.off_s && hourDecimal < retailer.off_e) {
                        touPeriod = 'Offpeak'; impRate = retailer.off_pk;
                    } else if (hourDecimal >= retailer.pk_s && hourDecimal < retailer.pk_e) {
                        touPeriod = 'Peak'; impRate = retailer.pk_pk;
                    }
                    // Feed-in priority: super peak (with daily limit) > peak > off-peak > shoulder (default)
                    if (hourDecimal >= retailer.sp_s && hourDecimal < retailer.sp_e && retailer.sp_limit > 0) {
                        var remaining = retailer.sp_limit - spExportUsed;
                        if (remaining > 0) {
                            var spPortion = Math.min(eKwh, remaining);
                            var fbPortion = eKwh - spPortion;
                            spExportUsed += spPortion;
                            expRate = retailer.sp_fit;
                            var fbRate = retailer.sh_fit;
                            if (hourDecimal >= retailer.pk_s && hourDecimal < retailer.pk_e) fbRate = retailer.pk_fit;
                            else if (hourDecimal >= retailer.off_s && hourDecimal < retailer.off_e) fbRate = retailer.off_fit;
                            if (fbPortion > 0) {
                                expRate = (spPortion * retailer.sp_fit + fbPortion * fbRate) / eKwh;
                            }
                        } else {
                            expRate = retailer.sh_fit;
                            if (hourDecimal >= retailer.pk_s && hourDecimal < retailer.pk_e) expRate = retailer.pk_fit;
                            else if (hourDecimal >= retailer.off_s && hourDecimal < retailer.off_e) expRate = retailer.off_fit;
                        }
                    } else {
                        if (hourDecimal >= retailer.sp_s && hourDecimal < retailer.sp_e) expRate = retailer.sp_fit;
                        else if (hourDecimal >= retailer.pk_s && hourDecimal < retailer.pk_e) expRate = retailer.pk_fit;
                        else if (hourDecimal >= retailer.off_s && hourDecimal < retailer.off_e) expRate = retailer.off_fit;
                    }
                    const impCost = totalImport * impRate;
                    const expCredit = eKwh * expRate;
                    intervals.push({
                        time: timeKey,
                        impKwh: Math.round(totalImport * 1000) / 1000,
                        expKwh: Math.round(eKwh * 1000) / 1000,
                        touPeriod: touPeriod,
                        impRate: impRate,
                        expRate: expRate,
                        impCost: Math.round(impCost * 1000) / 1000,
                        expCredit: Math.round(expCredit * 1000) / 1000
                    });
                }
            }
            let netTotal = 0;
            intervals.forEach(r => { netTotal += r.impCost - r.expCredit; });
            let rebate = 0;
            if (retailer.name.indexOf('Globird') >= 0 && eveningImport < 0.09) rebate = 1.00;
            netTotal += retailer.dsc - rebate;
            intervals.push({
                time: 'TOTAL',
                impKwh: '', expKwh: '', touPeriod: '',
                impRate: '', expRate: '',
                impCost: '', expCredit: '',
                eveningImport: eveningImport,
                netTotal: Math.round(netTotal * 100) / 100,
                dsc: retailer.dsc,
                rebate: rebate
            });
            fiveMinDetail[retailer.name][dateStr] = { intervals, summary: { eveningImport, netTotal: Math.round(netTotal * 100) / 100, dsc: retailer.dsc, rebate } };
        });
    });
}

// Store 5-min data in flow variable for HTTP endpoint (not in HA sensor)
flow.set('fiveMinDetail', fiveMinDetail);
// Also store metadata for the HA sensor
const fmRetailers = Object.keys(fiveMinDetail);
const fmDates = [...new Set(Object.values(fiveMinDetail).flatMap(r => Object.keys(r)))].sort();
msg.payload.fmRetailers = fmRetailers;
msg.payload.fmDates = fmDates;

// For backward compatibility, also set globird5min for yesterday
const globird5min = fiveMinDetail['Globird VPP'] ? fiveMinDetail['Globird VPP'][yesterdayStr]?.intervals || [] : [];

msg.payload = { totals, retailers, cheapest: cheapestName, savings: Math.round((flowpowerNet - cheapestNet) * 100) / 100, pea, flowRate, dailySummary, globird5min, fmRetailers, fmDates, todayDate: yesterdayStr };
return msg;

const totals = msg.payload.totals;
const retailers = msg.payload.retailers;
const cheapest = msg.payload.cheapest;
const savings = msg.payload.savings;
const pea = msg.payload.pea;
const flowRate = msg.payload.flowRate;
const haUrl = global.get('ha_url');
const haToken = global.get('ha_token');
const authHeader = 'Bearer ' + haToken;
const msgs = [];
const currentIds = retailers.map(r => r.sensor_id);
const previousIds = flow.get('retailer_sensor_ids') || [];
const staleIds = previousIds.filter(id => !currentIds.includes(id));
retailers.forEach(r => {
    const value = Math.round(totals[r.name].net * 100) / 100;
    const attrs = { friendly_name: r.name + ' Daily Cost', unit_of_measurement: '$', icon: 'mdi:cash', retailer_model: r.model, import_cost: Math.round(totals[r.name].import * 100) / 100, export_credit: Math.round(totals[r.name].export * 100) / 100 };
    if (r.model === 'hybrid') { attrs.pea = pea.toFixed(6); attrs.flow_rate = flowRate.toFixed(4); attrs.adj_import = Math.round(totals[r.name].adjImport * 100) / 100; attrs.adj_export = Math.round(totals[r.name].adjExport * 100) / 100; attrs.exp_outside_45c = Math.round(totals[r.name].expOutside45c * 100) / 100; }
    msgs.push({ payload: JSON.stringify({ state: value.toString(), attributes: attrs }), url: haUrl + '/api/states/' + r.sensor_id, headers: { Authorization: authHeader } });
});
msgs.push({ payload: JSON.stringify({ state: cheapest, attributes: { friendly_name: 'Cheapest Retailer Today', icon: 'mdi:trophy' } }), url: haUrl + '/api/states/sensor.retailer_cheapest', headers: { Authorization: authHeader } });
msgs.push({ payload: JSON.stringify({ state: savings.toString(), attributes: { friendly_name: 'Savings vs Flow Today', unit_of_measurement: '$', icon: 'mdi:piggy-bank' } }), url: haUrl + '/api/states/sensor.retailer_savings', headers: { Authorization: authHeader } });
flow.set('retailer_sensor_ids', currentIds);
const deleteMsgs = staleIds.map(id => ({ url: haUrl + '/api/states/' + id, headers: { Authorization: authHeader } }));
node.send([msgs, deleteMsgs]);

const dailySummary = msg.payload.dailySummary;
const retailers = msg.payload.retailers;
if (!dailySummary || Object.keys(dailySummary).length === 0) { return null; }
const haUrl = global.get('ha_url');
const haToken = global.get('ha_token');
const authHeader = 'Bearer ' + haToken;
const days = Object.keys(dailySummary).sort();
const rNames = retailers.map(r => r.name);

// Scrollable table with fixed header
let html = '<div style="max-height:400px;overflow-y:auto;border:1px solid #333;border-radius:4px">';
html += '<table style="width:100%;border-collapse:collapse;font-size:12px;table-layout:fixed">';
html += '<thead><tr style="background:#333;color:white;position:sticky;top:0;z-index:1">';
html += '<th style="padding:4px;text-align:left;min-width:100px">Date</th>';
rNames.forEach(name => { html += '<th style="padding:4px;text-align:right">' + name + '</th>'; });
html += '<th style="padding:4px;text-align:right;color:#4CAF50;min-width:100px">Cheapest</th></tr></thead><tbody>';
days.forEach((day, idx) => {
    const isToday = day === days[days.length - 1];
    const bg = isToday ? 'background:#1a1a2e;' : (idx % 2 === 0 ? 'background:#111;' : 'background:#1a1a1a;');
    const d = dailySummary[day];
    html += '<tr style="' + bg + '"><td style="padding:4px;text-align:left;color:#aaa">' + day + '</td>';
    rNames.forEach(name => {
        const val = d.retailers[name].net;
        const isCheapest = name === d.cheapest;
        const color = isCheapest ? '#4CAF50' : 'white';
        html += '<td style="padding:4px;text-align:right;color:' + color + '">$' + val.toFixed(2) + '</td>';
    });
    html += '<td style="padding:4px;text-align:right;color:#4CAF50;font-weight:bold">' + d.cheapest + '</td></tr>';
});
html += '<tr style="background:#222;border-top:1px solid #555"><td style="padding:4px;text-align:left;color:#aaa;font-weight:bold">Total</td>';
let cheapestTotal = '', cheapestTotalVal = Infinity;
rNames.forEach(name => {
    let total = 0;
    days.forEach(day => { total += dailySummary[day].retailers[name].net; });
    if (total < cheapestTotalVal) { cheapestTotalVal = total; cheapestTotal = name; }
});
rNames.forEach(name => {
    let total = 0;
    days.forEach(day => { total += dailySummary[day].retailers[name].net; });
    const color = name === cheapestTotal ? '#4CAF50' : 'white';
    html += '<td style="padding:4px;text-align:right;color:' + color + ';font-weight:bold">$' + total.toFixed(2) + '</td>';
});
html += '<td style="padding:4px;text-align:right;color:#4CAF50;font-weight:bold">' + cheapestTotal + '</td></tr>';
html += '</tbody></table></div>';

const attrs = {
    friendly_name: 'Daily Cost Summary',
    icon: 'mdi:chart-bar',
    days: days.length,
    billing_period: days[0] + ' to ' + days[days.length - 1],
